#pragma once
#include "kstationFlashStateTask.h"
namespace kstation {
class StartupConfigCopyTask final {
public:enum class Stage{BindSource,BindTarget,Count,Read,Write,Advance,Decrement,Repeat,Marker,WriteFirst,WriteSecond,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}unsigned index()const{return index_;}unsigned nextClocks(const FlashCredits&c)const{switch(stage_){case Stage::BindSource:case Stage::BindTarget:return 9;case Stage::Count:case Stage::Marker:return 6;case Stage::Read:return 5+c.read;case Stage::Write:return 3+c.write;case Stage::WriteFirst:case Stage::WriteSecond:return 9+c.write;case Stage::Return:return c.ret;case Stage::Complete:return 0;default:return 3;}}template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::Read:byte_=uint8_t(read(index_));break;case Stage::Write:write(index_,byte_);break;case Stage::Advance:++index_;break;case Stage::Repeat:if(index_<256)next=Stage::Read;break;case Stage::WriteFirst:write(256,0x50b0);break;case Stage::WriteSecond:write(258,0x50b0);break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::BindSource;unsigned index_=0;uint8_t byte_=0;};
class StartupQueueClearTask final {
public:enum class Stage{Retain,Clear,WriteProducer,WriteConsumer,Restore,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}unsigned nextClocks(const FlashCredits&c)const{switch(stage_){case Stage::Retain:return c.pushWord;case Stage::WriteProducer:case Stage::WriteConsumer:return 9+c.write;case Stage::Restore:return c.popWord;case Stage::Return:return c.ret;case Stage::Complete:return 0;default:return 3;}}template<class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;if(stage_==Stage::WriteProducer||stage_==Stage::WriteConsumer)write(stage_==Stage::WriteProducer,0);stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::Retain;};
class StartupStateCallTask final {
public:enum class Kind{Queue,Config};enum class Stage{Value,Publish,Call,Return,Complete};StartupStateCallTask(Kind kind=Kind::Queue):kind_(kind),stage_(kind==Kind::Queue?Stage::Value:Stage::Call){}Kind kind()const{return kind_;}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned nextClocks(const FlashCredits&c)const{return waiting_||complete()?0:stage_==Stage::Publish?(kind_==Kind::Queue?3:9)+c.write:stage_==Stage::Call?c.call:stage_==Stage::Return?c.ret:3;}template<class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;switch(stage_){case Stage::Value:stage_=Stage::Publish;break;case Stage::Publish:write(kind_==Kind::Queue?1:0);stage_=kind_==Kind::Queue?Stage::Call:Stage::Return;break;case Stage::Call:waiting_=true;stage_=kind_==Kind::Queue?Stage::Return:Stage::Value;break;case Stage::Return:stage_=Stage::Complete;break;default:break;}return cost;}
private:Kind kind_;Stage stage_;bool waiting_=false;};
class StartupBoundsTask final {
public:enum class Stage{Bind,Difference,Select,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}unsigned nextClocks(const FlashCredits&c)const{return complete()?0:stage_==Stage::Return?c.ret:stage_==Stage::Bind||stage_==Stage::Difference?9:3;}unsigned advanceBefore(unsigned budget,const FlashCredits&c){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::Bind;};
class StartupGlyphTask final {
public:enum class Stage{Address,Cgram,Pattern,Rows,CopyPattern,CountPattern,WritePattern,DecrementPattern,RepeatPattern,Clear,WriteClear,Bottom,WriteBottom,Shift,DecrementRows,RepeatRows,FinalValue,FinalCount,WriteFinal,DecrementFinal,RepeatFinal,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::Cgram:case Stage::WritePattern:return c.shortCall;case Stage::Pattern:case Stage::Rows:return 6;case Stage::WriteClear:case Stage::WriteBottom:case Stage::WriteFinal:return c.call;case Stage::Return:return c.ret;default:return 3;}}unsigned advanceBefore(unsigned budget,const FlashCredits&c){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::Cgram:case Stage::WritePattern:case Stage::WriteClear:case Stage::WriteBottom:case Stage::WriteFinal:waiting_=true;break;case Stage::Rows:rows_=6;break;case Stage::CountPattern:count_=6;break;case Stage::DecrementPattern:case Stage::DecrementFinal:--count_;break;case Stage::RepeatPattern:if(count_)next=Stage::WritePattern;break;case Stage::DecrementRows:--rows_;break;case Stage::RepeatRows:if(rows_)next=Stage::CopyPattern;break;case Stage::FinalCount:count_=8;break;case Stage::RepeatFinal:if(count_)next=Stage::WriteFinal;break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::Address;unsigned count_=0,rows_=0;bool waiting_=false;};
}
